import heapq


def shortest_windows(windows, parcels):
    ordered = sorted(windows)
    answer = [-1] * len(parcels)
    heap, i = [], 0
    for t, idx in sorted((t, idx) for idx, t in enumerate(parcels)):
        while i < len(ordered) and ordered[i][0] <= t:
            start, end = ordered[i]
            heapq.heappush(heap, (end - start, end))
            i += 1
        while heap and heap[0][1] <= t:
            heapq.heappop(heap)
        if heap:
            answer[idx] = heap[0][0]
    return answer
